module exp_backoff #(
  /// Seed for 16bit LFSR
  parameter int unsigned Seed   = 'hffff,
  /// 2**MaxExp-1 determines the maximum range from which random wait counts are drawn
  parameter int unsigned MaxExp = 16
) (
  input  logic clk_i,
  input  logic rst_ni,
  /// Sets the backoff counter (pulse) -> use when trial did not succeed
  input  logic set_i,
  /// Clears the backoff counter (pulse) -> use when trial succeeded
  input  logic clr_i,
  /// Indicates whether the backoff counter is equal to zero and a new trial can be launched
  output logic is_zero_o
);

  // leave this constant
  localparam int unsigned WIDTH = 16;

  logic [WIDTH-1:0] lfsr_d, lfsr_q, cnt_d, cnt_q, mask_d, mask_q;
  logic lfsr;

  // generate random wait counts
  // note: we use a flipped lfsr here to
  // avoid strange correlation effects between
  // the (left-shifted) mask and the lfsr
  assign lfsr = lfsr_q[15-15] ^
                lfsr_q[15-13] ^
                lfsr_q[15-12] ^
                lfsr_q[15-10];

  assign lfsr_d = (set_i) ? {lfsr, lfsr_q[$high(lfsr_q):1]} :
                            lfsr_q;

  // mask the wait counts with exponentially increasing mask (shift reg)
  assign mask_d = (clr_i) ? '0                                :
                  (set_i) ? {{(WIDTH-MaxExp){1'b0}},mask_q[MaxExp-2:0], 1'b1} :
                            mask_q;

  assign cnt_d =  (clr_i)      ? '0                :
                  (set_i)      ? (mask_q & lfsr_q) :
                  (!is_zero_o) ? cnt_q - 1'b1      : '0;

  assign is_zero_o = (cnt_q=='0);

  always_ff @(posedge clk_i or negedge rst_ni) begin : p_regs
    if (!rst_ni) begin
      lfsr_q <= WIDTH'(Seed);
      mask_q <= '0;
      cnt_q  <= '0;
    end else begin
      lfsr_q <= lfsr_d;
      mask_q <= mask_d;
      cnt_q  <= cnt_d;
    end
  end

///////////////////////////////////////////////////////
// assertions
///////////////////////////////////////////////////////

// assert wrong parameterizations
  initial begin                                        
    max_exp_0: assert (MaxExp>0)                            
      else begin                                       
        $error("[ASSERT FAILED] [%m] %s: %s (%s:%0d)", "max_exp_0", "MaxExp must be greater than 0", "/tmp/cva6_build/.bender/git/checkouts/common_cells-fcd36c2c56e22a95/src/exp_backoff.sv", 5); 
 
      end                                              
  end                                                  

  initial begin                                        
    max_exp_gt_16: assert (MaxExp<=16)                            
      else begin                                       
        $error("[ASSERT FAILED] [%m] %s: %s (%s:%0d)", "max_exp_gt_16", "MaxExp cannot be greater than 16", "/tmp/cva6_build/.bender/git/checkouts/common_cells-fcd36c2c56e22a95/src/exp_backoff.sv", 5); 
 
      end                                              
  end                                                  

  initial begin                                        
    seed_0: assert (Seed>0)                            
      else begin                                       
        $error("[ASSERT FAILED] [%m] %s: %s (%s:%0d)", "seed_0", "Zero seed is not allowed for LFSR", "/tmp/cva6_build/.bender/git/checkouts/common_cells-fcd36c2c56e22a95/src/exp_backoff.sv", 5); 
 
      end                                              
  end                                                  



endmodule // exp_backoff
